/*
  Placeholder jsPDF UMD shim
  - This is NOT the real jsPDF library.
  - It prevents errors when `window.jspdf` is expected, and shows a clear message to replace with the official build.
  - Replace with the official UMD build, for example:
    https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js
*/
(function(window){
    if (window.jspdf && window.jspdf.jsPDF) return;

    function JsPdfStub() {
        this._pages = [];
    }
    JsPdfStub.prototype.setFontSize = function(){};
    JsPdfStub.prototype.text = function(x,y,txt){ console.log('[jsPDF stub] text', x,y, txt); };
    JsPdfStub.prototype.addPage = function(){ this._pages.push([]); };
    JsPdfStub.prototype.splitTextToSize = function(txt, width){ return [txt]; };
    JsPdfStub.prototype.rect = function(){};
    JsPdfStub.prototype.line = function(){};
    JsPdfStub.prototype.setFillColor = function(){};
    JsPdfStub.prototype.setDrawColor = function(){};
    JsPdfStub.prototype.save = function(filename){
        alert('jsPDF not available. This is a placeholder. To enable PDF export, place the official jsPDF UMD file at public/js/jspdf.umd.min.js (see comments).');
        console.warn('Attempted to save PDF:', filename, ' — jsPDF is a stub. Replace with real library.');
    };

    window.jspdf = { jsPDF: JsPdfStub };
})(window);
